_WARNED = set()
def icon(name, sc=1.0, k="#0b2a4a"):
    if name not in ICONS and name not in _WARNED:
        _WARNED.add(name); import sys; print(f"WARNING: icon «{name}» does not exist, a star is drawn instead. Pick a name from CATALOG.md (icons).", file=sys.stderr)
    return f'<g transform="scale({sc})">' + ICONS.get(name, ICONS["star"]).replace("{k}", k) + "</g>"
import re as _re
def _dedupe(svg):   # one value per attribute inside each tag (first wins)
    def tag(m):
        seen = set(); out = []
        for a in _re.finditer(r'([\w:-]+)="[^"]*"', m.group(0)):
            if a.group(1) not in seen: seen.add(a.group(1)); out.append(a.group(0))
        name = _re.match(r"<(\w+)", m.group(0)).group(1); end = "/>" if m.group(0).endswith("/>") else ">"
        return f"<{name} " + " ".join(out) + end
    return _re.sub(r"<\w+\s[^<>]*?/?>", tag, svg)
ICONS = {k: _dedupe(v) for k, v in ICONS.items()}
NAMES = sorted(ICONS)
